import{_ as i,o as t,c as a,a0 as n}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Unified Studio","description":"Granular spec for the Studio layout, visual stage, and timeline.","frontmatter":{"isInternal":true,"type":"Specification","title":"Unified Studio","description":"Granular spec for the Studio layout, visual stage, and timeline.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/unified_studio.md","filePath":"specs/features/unified_studio.md"}'),o={name:"specs/features/unified_studio.md"};function r(s,e,l,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="unified-studio-technical-specification" tabindex="-1">Unified Studio Technical Specification <a class="header-anchor" href="#unified-studio-technical-specification" aria-label="Permalink to &quot;Unified Studio Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Unified Studio is the core editing environment of Sanjeev AI. It provides a split-pane layout consisting of a Timeline (left) and a Visual Stage / Cinema Player (right), enabling users to edit scripts, generate AI assets, and preview final renders in a single view.</p><h2 id="_2-component-architecture" tabindex="-1">2. Component Architecture <a class="header-anchor" href="#_2-component-architecture" aria-label="Permalink to &quot;2. Component Architecture&quot;">​</a></h2><ul><li><strong>StudioHeader</strong>: Top navigation bar containing project title, layout toggles (Tabbed vs Split), and the StudioToolbar.</li><li><strong>StudioToolbar</strong>: Action menu for triggering Automations, Visual Storyboarding, Audio Synthesis, Exporting, and YouTube Publishing.</li><li><strong>WorkspaceSplit</strong>: Manages the resizable split-pane layout for desktop, and the tabbed view for mobile.</li><li><strong>ScriptTimeline</strong>: Left panel. Renders the script as a series of editable scenes and lines. Integrates the VibeMap for scene-level art direction.</li><li><strong>VisualStage</strong>: Right panel. Renders the currently selected scene, allowing users to write prompts, generate static images (Imagen) or loop videos (Veo), and handle generation failures.</li><li><strong>CinemaPlayer</strong>: Right panel (alternative). An HTML5 video player overlay that plays the stitched final output when the user switches to &#39;cinema&#39; view mode.</li></ul><h2 id="_3-state-management" tabindex="-1">3. State Management <a class="header-anchor" href="#_3-state-management" aria-label="Permalink to &quot;3. State Management&quot;">​</a></h2><p>The Unified Studio manages complex asynchronous state:</p><ul><li><code>userCredits</code>: Fetched in real-time to disable generation buttons if overdrafted.</li><li><code>activeLineIndex</code>: Tracks which script line the user is currently editing or previewing.</li><li><code>audioUrl</code> &amp; <code>finalVideoUrl</code>: Derived artifacts from the generation processes.</li><li><code>layoutMode</code> / <code>viewMode</code>: UI toggles synced to local preferences.</li></ul>',8)])])}const g=i(o,[["render",r]]);export{h as __pageData,g as default};
